CREATE OR REPLACE VIEW P_LEW_MART_WFM.V_SEASON_WAREHOUSE_SUBITEMGRP_1
/**************************************************************************
* Automated generated by U_F_ADMIN_SYS
* on 19/04/25    12:18:10+02:00
**************************************************************************/
/*
#DescStart#
#$Revision: 11110 $, $LastChangedBy: iakin $
#SubjectAreas#: Access Layer
#DescEnd#
*/
(
     iso_cd
    ,dat_calendar
    ,wh_id
    ,subitemgroup_id
    ,currency_iso_cd
    ,write_off_gross
    ,write_off_net
    ,price_change_gross
    ,price_change_net
    ,turnover_gross
    ,turnover_net
    ,update_timestamp
)
AS
   SELECT
        COALESCE(wo_pc.iso_cd, to_sub.iso_cd) AS iso_cd,
   COALESCE(wo_pc.dat_calendar, to_sub.dat_calendar) AS dat_calendar,
   COALESCE(wo_pc.wh_id, to_sub.wh_id) AS wh_id,
   COALESCE(wo_pc.subitemgroup_id, to_sub.subitemgroup_id) AS subitemgroup_id,
   COALESCE(wo_pc.currency_iso_cd, to_sub.currency_iso_cd) AS currency_iso_cd,
   wo_pc.AbschriftenWertTotalBrutto AS write_off_gross,
   wo_pc.AbschriftenWertTotalNetto AS write_off_net,
   wo_pc.PVWertTotalBrutto AS price_change_gross,
   wo_pc.PVWertTotalNetto AS price_change_net,
   to_sub.UmsatzBrutto AS turnover_gross,
   to_sub.UmsatzNetto AS turnover_net,
   TO_TIMESTAMP( GREATEST( COALESCE( TO_CHAR(wo_pc.update_timestamp,'yyyymmddhh24missff6'), '19000101000000000000') ,
                               COALESCE( TO_CHAR(to_sub.update_timestamp,'yyyymmddhh24missff6'), '19000101000000000000')), 'yyyymmddhh24missff6') AS update_timestamp
   FROM    (SELECT
        NVL(item.subitemgroup_id,-666) AS subitemgroup_id /*for not matching values of subitemgroup_id, -666 is used since on full join both side does not match*/,
   agg_wh_item_sfo.booking_dat AS dat_calendar,
   agg_wh_item_sfo.wh_id AS wh_id,
   agg_wh_item_sfo.client_id AS client_id,
   cli.country_cd AS iso_cd,
   agg_wh_item_sfo.currency_iso_cd AS currency_iso_cd,
   MAX(run_log_loc.update_timestamp) AS update_timestamp,
   SUM(CASE WHEN agg_wh_item_sfo.sfotype_id IN (137,147,181,182,191,192) THEN NVL(agg_wh_item_sfo.sfo_wrtoff_zero_rtl_rl_val_asis,0)+NVL(agg_wh_item_sfo.sfo_total_rtl_rl_val_asis,0) ELSE NULL END) AS AbschriftenWertTotalBrutto,
   SUM(CASE WHEN agg_wh_item_sfo.sfotype_id IN (137,147,181,182,191,192) THEN NVL(agg_wh_item_sfo.sfo_wrtoff_zero_rtl_rl_net_val_asis,0)+NVL(agg_wh_item_sfo.sfo_total_rtl_rl_net_val_asis,0) ELSE NULL END) AS AbschriftenWertTotalNetto,
   SUM(CASE WHEN agg_wh_item_sfo.sfotype_id in (144, 134, 180, 190) THEN agg_wh_item_sfo.sfo_total_rtl_rl_val_asis ELSE NULL END) AS PVWertTotalBrutto,
   SUM(CASE WHEN agg_wh_item_sfo.sfotype_id in (144, 134, 180, 190) THEN agg_wh_item_sfo.sfo_total_rtl_rl_net_val_asis ELSE NULL END) AS PVWertTotalNetto
   FROM    (SELECT  agg_wh_sfo.client_id,
   agg_wh_sfo.loc_sid_wh,
   wh.src_wh_id AS wh_id,
   itmp.item_sid_map AS item_id,
   agg_wh_sfo.booking_dat,
   agg_wh_sfo.curr_cd_from AS currency_iso_cd,
   agg_wh_sfo.sfotype_id,
   agg_wh_sfo.sfo_wrtoff_zero_rtl_rl_val_asis,
   agg_wh_sfo.sfo_total_rtl_rl_val_asis,
   agg_wh_sfo.sfo_wrtoff_zero_rtl_rl_net_val_asis,
   agg_wh_sfo.sfo_total_rtl_rl_net_val_asis
         FROM p_lew_bil_ac.v_agg_wh_day_item_sfo_asis_1 AS agg_wh_sfo
   INNER JOIN p_lew_bil_ac.v_warehouse_1 AS wh
   ON agg_wh_sfo.client_id=wh.client_id
   AND agg_wh_sfo.loc_sid_wh=wh.loc_sid_wh
   AND wh.dwh_actual_fg = 1
   INNER JOIN p_lew_core_ac.v_item_map_key_1 AS itmp
   ON itmp.client_id = agg_wh_sfo.client_id
   AND itmp.item_sid = agg_wh_sfo.item_sid
) AS agg_wh_item_sfo
   LEFT JOIN (SELECT
   vi.client_id,
   CAST(vi.item_sid AS DECIMAL(18,0)) AS item_id,
   CASE WHEN vi.src_matnr IS NULL THEN wawi.subitemgroup_id ELSE CAST(vig.src_matkl AS INTEGER) END AS subitemgroup_id
                          FROM p_lew_core_ac.v_item_1 AS vi
   INNER JOIN p_lew_core_ac.v_item_hist_1 AS vih
   ON vih.client_id = vi.client_id
   AND vih.item_sid = vi.item_sid
   AND CURRENT_DATE BETWEEN vih.dwh_valid_from AND vih.dwh_valid_to
   LEFT JOIN p_lew_core_ac.v_item_group_1 AS vig
   ON vig.client_id = vih.client_id
   AND vig.item_grp_sid = vih.item_grp_sid
   LEFT JOIN p_lew_core_ac.v_wawi_itm_item_act_1 AS wawi
   ON wawi.client_id = vi.client_id
   AND wawi.item_sid = vi.item_sid
) AS item_1
   ON (agg_wh_item_sfo.client_id = item.client_id
   AND agg_wh_item_sfo.item_id = item.item_id)
   INNER JOIN p_lew_core_ac.v_wawi_ref_currency_act_1 AS curr
   ON (agg_wh_item_sfo.client_id = curr.client_id
   AND agg_wh_item_sfo.currency_iso_cd = curr.currency_iso_cd)
   INNER JOIN p_lew_core_ac.v_client_1 AS cli
   ON cli.client_id = curr.client_id
   AND cli.curr_cd = curr.currency_iso_cd
   INNER JOIN (SELECT
   client_id,
   dwh_cal_dt,
   MAX(update_timestamp) update_timestamp
                  FROM p_lew_process_ac.v_agc_run_log_location_1
                 WHERE aggregate_name = 't_agg_store_day_item_sfo_1'
                 GROUP BY client_id, dwh_cal_dt
            ) run_log_loc
   ON (
   run_log_loc.client_id = agg_wh_item_sfo.client_id
AND run_log_loc.dwh_cal_dt = agg_wh_item_sfo.booking_dat
  )
GROUP BY  NVL(item.subitemgroup_id,-666)
   ,agg_wh_item_sfo.booking_dat
   ,agg_wh_item_sfo.wh_id
   ,agg_wh_item_sfo.client_id
   ,cli.country_cd
   ,agg_wh_item_sfo.currency_iso_cd ) AS wo_pc
   FULL OUTER JOIN
   (SELECT
           NVL(item_q.subitemgroup_id,-666) AS subitemgroup_id /*for not matching values of subitemgroup_id, -666 is used since on full join both side does not match*/,
   agg_pos_wh_item.dwh_cal_dt AS dat_calendar,
   agg_pos_wh_item.wh_id AS wh_id,
   agg_pos_wh_item.client_id AS client_id,
   clie.country_cd AS iso_cd,
   agg_pos_wh_item.currency_iso_cd AS currency_iso_cd,
   MAX(run_log.update_timestamp) AS update_timestamp,
   SUM(NVL(agg_pos_wh_item.sales_gross_val / agg_pos_wh_item.rate_currency_exchange,0) + NVL(agg_pos_wh_item.return_gross_val / agg_pos_wh_item.rate_currency_exchange,0)) AS UmsatzBrutto,
   SUM(NVL(agg_pos_wh_item.sales_net_val / agg_pos_wh_item.rate_currency_exchange,0) + NVL(agg_pos_wh_item.return_net_val / agg_pos_wh_item.rate_currency_exchange,0)) AS UmsatzNetto
   FROM (SELECT
            agg_pos_wh.dwh_cal_dt,
   agg_pos_wh.client_id,
   agg_pos_wh.sales_gross_val,
   agg_pos_wh.sales_net_val,
   agg_pos_wh.return_gross_val,
   agg_pos_wh.return_net_val,
   itmp.item_sid_map AS item_id,
   cry.currency_iso_cd,
   cry.rate_currency_exchange,
   wh.src_wh_id AS wh_id
         FROM p_lew_bil_ac.v_agg_pos_wh_day_item_asis_1 AS agg_pos_wh
   INNER JOIN p_lew_bil_ac.v_warehouse_1 AS wh
   ON wh.client_id = agg_pos_wh.client_id
   AND wh.loc_sid_wh = agg_pos_wh.loc_sid_wh
   AND wh.dwh_actual_fg = 1
   INNER JOIN p_lew_core_ac.v_wawi_ref_client_currency_rate_1 AS cry
   ON agg_pos_wh.client_id = cry.client_id
   AND CURRENT_DATE BETWEEN cry.dat_rec_start AND cry.dat_rec_end
   INNER JOIN p_lew_core_ac.v_item_map_key_1 AS itmp
   ON itmp.client_id = agg_pos_wh.client_id
   AND itmp.item_sid = agg_pos_wh.item_sid
  ) AS agg_pos_wh_item
   LEFT JOIN (SELECT
   vi.client_id,
   CAST(vi.item_sid AS DECIMAL(18,0)) AS item_id,
   CASE WHEN vi.src_matnr IS NULL THEN wawi.subitemgroup_id ELSE CAST(vig.src_matkl AS INTEGER) END AS subitemgroup_id
                       FROM p_lew_core_ac.v_item_1 AS vi
   INNER JOIN p_lew_core_ac.v_item_hist_1 AS vih
   ON vih.client_id = vi.client_id
   AND vih.item_sid = vi.item_sid
   AND CURRENT_DATE BETWEEN vih.dwh_valid_from AND vih.dwh_valid_to
   LEFT JOIN p_lew_core_ac.v_item_group_1 AS vig
   ON vig.client_id = vih.client_id
   AND vig.item_grp_sid = vih.item_grp_sid
   LEFT JOIN p_lew_core_ac.v_wawi_itm_item_act_1 AS wawi
   ON wawi.client_id = vi.client_id
   AND wawi.item_sid = vi.item_sid
) AS item_q
   ON (agg_pos_wh_item.client_id = item_q.client_id
   AND agg_pos_wh_item.item_id = item_q.item_id)
   INNER JOIN p_lew_core_ac.v_wawi_ref_currency_act_1 ref_curr
   ON (agg_pos_wh_item.client_id = ref_curr.client_id
   AND agg_pos_wh_item.currency_iso_cd = ref_curr.currency_iso_cd)
   INNER JOIN p_lew_core_ac.v_client_1 AS clie
   ON clie.client_id = ref_curr.client_id
   AND clie.curr_cd = ref_curr.currency_iso_cd
   INNER JOIN (SELECT
   client_id,
   dwh_cal_dt,
   MAX(update_timestamp) update_timestamp
                  FROM p_lew_process_ac.v_agc_run_log_1
                 WHERE aggregate_name = 't_agg_pos_wh_day_item_asis_1'
                 GROUP BY client_id, dwh_cal_dt
            ) AS run_log
   ON (run_log.client_id = agg_pos_wh_item.client_id
   AND run_log.dwh_cal_dt = agg_pos_wh_item.dwh_cal_dt)
GROUP BY  NVL(item_q.subitemgroup_id,-666)
       ,agg_pos_wh_item.dwh_cal_dt
       ,agg_pos_wh_item.wh_id
       ,agg_pos_wh_item.client_id
       ,clie.country_cd
       ,agg_pos_wh_item.currency_iso_cd) AS to_sub
   ON (wo_pc.client_id = to_sub.client_id
   AND wo_pc.dat_calendar = to_sub.dat_calendar
   AND wo_pc.subitemgroup_id = to_sub.subitemgroup_id
   AND wo_pc.wh_id = to_sub.wh_id
   AND wo_pc.iso_cd = to_sub.iso_cd
   AND wo_pc.currency_iso_cd = to_sub.currency_iso_cd
);